files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #2b2b2b;
  background-image:
    linear-gradient(45deg, #3a3a3a 25%, transparent 25%),
    linear-gradient(-45deg, #3a3a3a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #3a3a3a 75%),
    linear-gradient(-45deg, transparent 75%, #3a3a3a 75%);
  background-size: 8px 8px;
  background-position: 0 0, 0 4px, 4px -4px, -4px 0px;
  color: #fff;
  font-family: 'Courier New', monospace;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  image-rendering: pixelated;
}

.app {
  background: #4a4a4a;
  border: 4px solid #fff;
  box-shadow: 8px 8px 0 #000;
  padding: 20px;
  width: min(92%, 480px);
}

h1 {
  margin: 0 0 16px;
  font-size: 2rem;
  text-transform: uppercase;
  color: #f9f871;
  text-shadow: 3px 3px #000;
}

#todo-form {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

#todo-input {
  flex: 1;
  padding: 10px;
  background: #1e1e1e;
  color: #fff;
  border: 3px solid #fff;
  font: inherit;
  outline: none;
}

#todo-input:focus-visible {
  outline: 3px dashed #f9f871;
  outline-offset: 2px;
}

#todo-add {
  padding: 10px 14px;
  background: #00b8b8;
  color: #000;
  border: 3px solid #fff;
  font: inherit;
  font-weight: bold;
  cursor: pointer;
}

#todo-add:active {
  transform: translate(2px, 2px);
}

.stats {
  display: flex;
  justify-content: space-between;
  background: #2a2a2a;
  border: 2px dashed #fff;
  padding: 8px 12px;
  margin-bottom: 16px;
}

.stats p {
  margin: 0;
}

#todo-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

#todo-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #3a3a3a;
  border: 2px solid #fff;
  padding: 8px;
  margin-bottom: 8px;
}

#todo-list li.task-done {
  opacity: 0.65;
}

#todo-list li.task-done span {
  text-decoration: line-through;
}

#todo-list input[type=checkbox] {
  width: 20px;
  height: 20px;
  accent-color: #f9f871;
  cursor: pointer;
}

#todo-list span {
  flex: 1;
  overflow-wrap: anywhere;
}

#todo-list button {
  background: #e63946;
  color: #fff;
  border: 2px solid #fff;
  padding: 4px 8px;
  font: inherit;
  cursor: pointer;
}

#todo-list button:active {
  transform: translate(1px, 1px);
}

button:focus-visible,
input[type=checkbox]:focus-visible {
  outline: 3px dashed #f9f871;
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

(() => {
  'use strict';

  const form = document.getElementById('todo-form');
  const input = document.getElementById('todo-input');
  const list = document.getElementById('todo-list');
  const totalEl = document.getElementById('todo-total');
  const remainingEl = document.getElementById('remaining');

  let nextId = 1;
  let total = 0;
  let remaining = 0;

  const updateCounts = () => {
    totalEl.textContent = String(total);
    remainingEl.textContent = String(remaining);
  };

  const addTask = (text) => {
    const id = nextId++;
    const li = document.createElement('li');
    li.id = `todo-item-${id}`;

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `todo-check-${id}`;
    checkbox.setAttribute('aria-label', `Task ${id} completed`);

    const span = document.createElement('span');
    span.id = `todo-text-${id}`;
    span.textContent = text;

    const del = document.createElement('button');
    del.type = 'button';
    del.id = `todo-delete-${id}`;
    del.textContent = 'Delete';
    del.setAttribute('aria-label', `Delete task ${id}`);

    li.append(checkbox, span, del);
    list.appendChild(li);

    total += 1;
    remaining += 1;
    updateCounts();

    checkbox.addEventListener('change', () => {
      const isChecked = checkbox.checked;
      remaining += isChecked ? -1 : 1;
      li.classList.toggle('task-done', isChecked);
      updateCounts();
    });

    del.addEventListener('click', () => {
      li.remove();
      total -= 1;
      if (!checkbox.checked) {
        remaining -= 1;
      }
      updateCounts();
    });
  };

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const text = input.value.trim();
    if (text === '') return;
    addTask(text);
    input.value = '';
    input.focus();
  });

  updateCounts();
})();
